type FrozenRequeueAttestedFinalizeRunsParams struct {
	MaxRequeues      int32       `json:"max_requeues"`
	WorkerID         pgtype.UUID `json:"worker_id"`
	RunIds           []uuid.UUID `json:"run_ids"`
	ClaimGenerations []int64     `json:"claim_generations"`
	FrozenTargets    []byte      `json:"frozen_targets"`
	LockedParentIds  []uuid.UUID `json:"locked_parent_ids"`
}

type FrozenRequeueAttestedFinalizeRunsRow struct {
	ID            uuid.UUID `json:"id"`
	AllowanceUsed bool      `json:"allowance_used"`
}

// Under budget: an ordinary requeue (the allowance mark is NOT set). Over budget: the one-shot
// allowance (@max_requeues > 0 and finalize_resume_generation still NULL) requeues once more and
// stamps finalize_resume_generation = claim_generation. Never decrements requeue_count.
// RETURNING allowance_used tells the caller which case fired (the mark equals the generation the
// run held when re-queued; claim_generation is unchanged until the next ClaimRun).
func (q *Queries) FrozenRequeueAttestedFinalizeRuns(ctx context.Context, arg FrozenRequeueAttestedFinalizeRunsParams) ([]FrozenRequeueAttestedFinalizeRunsRow, error) {
	rows, err := q.db.Query(ctx, frozenRequeueAttestedFinalizeRuns,
		arg.MaxRequeues,
		arg.WorkerID,
		arg.RunIds,
		arg.ClaimGenerations,
		arg.FrozenTargets,
		arg.LockedParentIds,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []FrozenRequeueAttestedFinalizeRunsRow{}
	for rows.Next() {
		var i FrozenRequeueAttestedFinalizeRunsRow
		if err := rows.Scan(&i.ID, &i.AllowanceUsed); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

