type FrozenRequeueRunsMissingFromSnapshotParams struct {
	Now                  pgtype.Timestamptz `json:"now"`
	WorkerID             pgtype.UUID        `json:"worker_id"`
	MissingCutoff        pgtype.Timestamptz `json:"missing_cutoff"`
	MaxRequeues          int32              `json:"max_requeues"`
	GlobalTimeoutSeconds int32              `json:"global_timeout_seconds"`
	FrozenTargets        []byte             `json:"frozen_targets"`
	LockedParentIds      []uuid.UUID        `json:"locked_parent_ids"`
}

type FrozenRequeueRunsMissingFromSnapshotRow struct {
	ID     uuid.UUID `json:"id"`
	UserID uuid.UUID `json:"user_id"`
	Status string    `json:"status"`
}

// PRD #1390 M2b (SC2, under cap): the requeue twin of FailRunsMissingFromSnapshot — a `running`
// run-lane run this worker OWNS but no longer lists, past the fence and within budget, is REQUEUED
// through the existing requeue path. Its SET list mirrors RequeueRunsOfStaleWorkers (health reset,
// park-time bank for approval/input — a no-op here since only status='running' is targeted, codex
// cap revocation, requeue_count++). It does NOT set stale_requeue_generation: a genuine loss is
// never refunded (D2). Chat is a target restriction (kind <> 'chat', D10).
func (q *Queries) FrozenRequeueRunsMissingFromSnapshot(ctx context.Context, arg FrozenRequeueRunsMissingFromSnapshotParams) ([]FrozenRequeueRunsMissingFromSnapshotRow, error) {
	rows, err := q.db.Query(ctx, frozenRequeueRunsMissingFromSnapshot,
		arg.Now,
		arg.WorkerID,
		arg.MissingCutoff,
		arg.MaxRequeues,
		arg.GlobalTimeoutSeconds,
		arg.FrozenTargets,
		arg.LockedParentIds,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []FrozenRequeueRunsMissingFromSnapshotRow{}
	for rows.Next() {
		var i FrozenRequeueRunsMissingFromSnapshotRow
		if err := rows.Scan(&i.ID, &i.UserID, &i.Status); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

