type FrozenRequeueWorkerRunsParams struct {
	WorkerID        pgtype.UUID `json:"worker_id"`
	MaxRequeues     int32       `json:"max_requeues"`
	FrozenTargets   []byte      `json:"frozen_targets"`
	LockedParentIds []uuid.UUID `json:"locked_parent_ids"`
}

// Within budget → re-queued to this same worker (affinity), which then re-claims
// and resumes from the persisted session (handles docker compose down && up).
//
// PRD #1390 M2a: RETURNING id so Register can publish each requeue transition post-commit
// (via publishSwept) exactly as the sweeper's RequeueRunsOfStaleWorkers twin already does —
// closing the gap where a register-time requeue reached no live channel.
func (q *Queries) FrozenRequeueWorkerRuns(ctx context.Context, arg FrozenRequeueWorkerRunsParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, frozenRequeueWorkerRuns,
		arg.WorkerID,
		arg.MaxRequeues,
		arg.FrozenTargets,
		arg.LockedParentIds,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

