type UpsertFrozenWorkerActiveRunParams struct {
	WorkerID        uuid.UUID          `json:"worker_id"`
	RunID           uuid.UUID          `json:"run_id"`
	ClaimGeneration int64              `json:"claim_generation"`
	Phase           string             `json:"phase"`
	TerminalPending bool               `json:"terminal_pending"`
	LeaseSeconds    int32              `json:"lease_seconds"`
	PendingSince    pgtype.Timestamptz `json:"pending_since"`
	SnapshotEpoch   int64              `json:"snapshot_epoch"`
	FrozenTargets   []byte             `json:"frozen_targets"`
	LockedParentIds []uuid.UUID        `json:"locked_parent_ids"`
}

// Internal transaction seam: the caller has already held the frozen parents and
// prelocked snapshot targets. Fence membership and current identity before the
// INSERT can acquire FK locks. An unchanged orphan can be recorded here; this
// snapshot write does not admit or re-execute it.
// Reported claim_generation remains independent of the frozen server generation,
// preserving UpsertWorkerActiveRun storage, lease, pending-since and epoch behavior.
func (q *Queries) UpsertFrozenWorkerActiveRun(ctx context.Context, arg UpsertFrozenWorkerActiveRunParams) (int64, error) {
	result, err := q.db.Exec(ctx, upsertFrozenWorkerActiveRun,
		arg.WorkerID,
		arg.RunID,
		arg.ClaimGeneration,
		arg.Phase,
		arg.TerminalPending,
		arg.LeaseSeconds,
		arg.PendingSince,
		arg.SnapshotEpoch,
		arg.FrozenTargets,
		arg.LockedParentIds,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

